"""HTTP/1.1 framing of compressed recordings and paired provenance evidence.

Only line-sized ranges are decoded. Opaque length/chunk data is skipped by
signed-64-bit offsets and summarized through the byte rope algebra.
"""
from bisect import bisect_right
from functools import lru_cache
import re
from modules.byte_program import MAX, literal, size, join, cut, fingerprint, next_lf, read

TOKEN = re.compile(rb"[!#$%&'*+.^_`|~0-9A-Za-z-]+\Z")
VISIBLE = re.compile(rb'[\x21-\x7e]+\Z')
VALUE = re.compile(rb'[\x20-\x7e\t]*\Z')
DECIMAL = re.compile(rb'[0-9]+\Z')
HEX = re.compile(rb'[0-9A-Fa-f]+\Z')


class FramingError(Exception):
    def __init__(self, kind):
        self.kind = kind


def syntax():
    raise FramingError('syntax')


def incomplete():
    raise FramingError('incomplete')


@lru_cache(maxsize=4096)
def field(line):
    name, colon, value = line.partition(b':')
    if not colon or not TOKEN.fullmatch(name) or not VALUE.fullmatch(value):
        syntax()
    return name, value.strip(b' \t')


@lru_cache(maxsize=1024)
def field_fingerprint(fields):
    # Compose summaries of the individual strings. Repeated large field values
    # need not be re-hashed just because another field in the block changes.
    h, n = 0, 0
    for data in _encoded_fields(fields):
        node = literal(data)
        if node is not None:
            h = (h * node.p + node.h) & ((1 << 64)-1)
            n += node.n
    return {'n': n, 'h': f'{h:016x}'}


def _encoded_fields(fields):
    yield len(fields).to_bytes(8, 'big')
    for name, value in fields:
        yield len(name).to_bytes(8, 'big')
        yield name
        yield len(value).to_bytes(8, 'big')
        yield value


def unsigned(text, base):
    if not (DECIMAL if base == 10 else HEX).fullmatch(text):
        syntax()
    significant = text.lstrip(b'0')
    if len(significant) > (19 if base == 10 else 16):
        syntax()
    value = int(significant or b'0', base)
    if value > MAX:
        syntax()
    return value


@lru_cache(maxsize=1024)
def framing_headers(headers):
    hosts, lengths, encodings = [], [], []
    for name, value in headers:
        lower = name.lower()
        if lower == b'host':
            hosts.append(value.lower())
        elif lower == b'content-length':
            lengths.extend(unsigned(member.strip(b' \t'), 10) for member in value.split(b','))
        elif lower == b'transfer-encoding':
            encodings.append(value.lower())
    if (lengths and any(n != lengths[0] for n in lengths)
            or encodings and (lengths or encodings != [b'chunked'])):
        syntax()
    return len(hosts), hosts[0] if len(hosts) == 1 else b'', (
        'chunked' if encodings else 'length' if lengths else 'none'), lengths[0] if lengths else 0


@lru_cache(maxsize=4096)
def chunk_size(line):
    number, sep, suffix = line.partition(b';')
    n = unsigned(number, 16)
    if sep and not VALUE.fullmatch(suffix):
        syntax()
    return n


class Parser:
    def __init__(self, data, budget):
        self.data, self.n, self.pos, self.budget = data, size(data), 0, budget
        self.buffer, self.base = b'', 0

    def line(self):
        at = self.pos
        local = at-self.base
        if 0 <= local < len(self.buffer):
            lf = self.buffer.find(b'\n', local)
        else:
            lf = -1
        if lf < 0 and self.base+len(self.buffer) < self.n or not 0 <= local <= len(self.buffer):
            self.base = at
            self.buffer = read(self.data, at, min(at+65536, self.n))
            local = 0
            lf = self.buffer.find(b'\n')
        if lf < 0:
            if len(self.buffer)-local > 8193:
                syntax()
            incomplete()
        if lf-local > 8193 or lf == local or self.buffer[lf-1] != 13:
            syntax()
        self.pos = self.base+lf+1
        return self.buffer[local:lf-1]

    def fields(self, block_start, trailer=False):
        result = []
        while True:
            line = self.line()
            if self.pos-block_start > 65536:
                syntax()
            if not line:
                return result
            if len(result) == 128:
                syntax()
            name, value = field(line)
            if trailer and name.lower() in (b'host', b'content-length', b'transfer-encoding'):
                syntax()
            result.append((name, value))

    def request(self):
        start = self.pos
        request_line = self.line()
        words = request_line.split(b' ')
        if (len(words) != 3 or not TOKEN.fullmatch(words[0])
                or not VISIBLE.fullmatch(words[1]) or words[2] != b'HTTP/1.1'):
            syntax()
        method, target = words[:2]
        headers = tuple(self.fields(start))
        host_count, host, framing, length = framing_headers(headers)
        trailers, body = [], None
        if framing == 'chunked':
            chunks = []
            while True:
                line = self.line()
                self.budget[1] += 1
                if self.budget[1] > 40000:
                    raise ValueError('chunk line budget')
                n = chunk_size(line)
                if n == 0:
                    trailers = self.fields(self.pos, trailer=True)
                    break
                if self.n-self.pos < n:
                    incomplete()
                chunks.append(cut(self.data, self.pos, self.pos+n))
                self.pos += n
                if self.n-self.pos < 2:
                    incomplete()
                if read(self.data, self.pos, self.pos+2) != b'\r\n':
                    syntax()
                self.pos += 2
            body = join(chunks)
        elif framing == 'length':
            n = length
            if self.n-self.pos < n:
                incomplete()
            body = cut(self.data, self.pos, self.pos+n)
            self.pos += n
        else:
            framing = 'none'
        self.budget[0] += 1
        if self.budget[0] > 20000:
            raise ValueError('origin request budget')
        record = {'start': start, 'end': self.pos,
                  'method': fingerprint(literal(method)), 'target': fingerprint(literal(target)),
                  'host': fingerprint(literal(host)), 'host_count': host_count,
                  'headers': field_fingerprint(tuple(headers)), 'body': fingerprint(body),
                  'trailers': field_fingerprint(tuple(trailers)), 'framing': framing}
        return record, method, target, host


def audit_channels(channels, cases, sent):
    expectations = {case['name']: {k: v.encode('ascii') for k, v in case['expect'].items()}
                    for case in cases}
    case_records = {case['name']: case for case in sent}
    case_flags = {case['name']: set() for case in sent}
    budget, output = [0, 0], []
    for channel in channels:
        parts = channel['parts']
        ends, total = [], 0
        for part in parts:
            total += size(part['data'])
            if total > MAX:
                raise ValueError('channel length')
            ends.append(total)
        data = join(part['data'] for part in parts)
        parser, requests, error = Parser(data, budget), [], None
        while parser.pos < total:
            start = parser.pos
            try:
                record, method, target, host = parser.request()
            except FramingError as exc:
                error = {'kind': exc.kind, 'offset': start}
                break
            end = record['end']
            index = bisect_right(ends, start)
            owner = parts[index]['case']
            counts = {}
            while index < len(parts):
                part_start = ends[index-1] if index else 0
                if part_start >= end:
                    break
                n = min(end, ends[index])-max(start, part_start)
                if n > 0:
                    label = parts[index]['case']
                    counts[label] = counts.get(label, 0)+n
                index += 1
            flags = set()
            if record['host_count'] == 0:
                flags.add('missing_host')
            elif record['host_count'] > 1:
                flags.add('multiple_host')
            if any(label != owner for label in counts):
                flags.add('mixed_owner')
            if owner is None:
                flags.add('unattributed')
            else:
                case = case_records[owner]
                expected = expectations[owner]
                if (method != expected['method'] or target != expected['target']
                        or record['host_count'] != 1 or host != expected['host'].lower()):
                    flags.add('identity')
                    case_flags[owner].add('identity')
                if case['origin_count']:
                    flags.add('extra')
                if not case['request_frames']:
                    flags.add('unsent')
                if 'mixed_owner' in flags:
                    case_flags[owner].add('mixed_origin')
                case['origin_count'] += 1
            record.update(owner=owner, owners=[[label, n] for label, n in counts.items()],
                          flags=sorted(flags))
            requests.append(record)
        request_ends = [record['end'] for record in requests]
        output.append({'name': channel['name'], 'bytes': fingerprint(data), 'requests': requests,
                       'committed': [bisect_right(request_ends, end) for end in ends], 'error': error})
    for case in sent:
        flags = case_flags[case['name']]
        if case['request_frames'] > 0 and case['origin_count'] == 0:
            flags.add('missing_origin')
        if case['origin_count'] > 1:
            flags.add('extra_origin')
        if case['origin_count'] > 0 and case['request_frames'] == 0:
            flags.add('unsent_origin')
        case['flags'] = sorted(flags)
    return output
"""Immutable, shared byte ropes with exact composable polynomial checksums.

Repeats never expand. Concat nodes are AVL balanced; slicing walks only the
boundary paths and preserves shared interior subtrees.
"""
import ast
import hashlib
import keyword
import re
from functools import lru_cache
from collections import OrderedDict

MAX = (1 << 63) - 1
MASK = (1 << 64) - 1
MOD = 1 << 64


class Bytes:
    __slots__ = ('kind', 'n', 'h', 'p', 'height', 'lf', 'a', 'b')

    def __init__(self, kind, n, h, p, height, lf, a, b=None):
        self.kind, self.n, self.h, self.p = kind, n, h, p
        self.height, self.lf, self.a, self.b = height, lf, a, b


_literals = OrderedDict()
_literal_bytes = 0


def literal(data):
    global _literal_bytes
    if not data:
        return None
    cached = _literals.get(data)
    if cached is not None:
        _literals.move_to_end(data)
        return cached
    h = 0
    for c in data:
        h = (h * 257 + c + 1) & MASK
    node = Bytes(0, len(data), h, pow(257, len(data), MOD), 1,
                 data.find(b'\n'), data)
    _literals[data] = node
    _literal_bytes += len(data)
    while _literal_bytes > 8*1024*1024 or len(_literals) > 8192:
        old, _ = _literals.popitem(last=False)
        _literal_bytes -= len(old)
    return node


def size(node):
    return node.n if node is not None else 0


def _pair(a, b):
    n = a.n + b.n
    if n > MAX:
        raise ValueError('byte length')
    return Bytes(1, n, (a.h * b.p + b.h) & MASK, a.p * b.p & MASK,
                 max(a.height, b.height) + 1,
                 a.lf if a.lf >= 0 else (a.n + b.lf if b.lf >= 0 else -1), a, b)


def _balance(a, b):
    if a.height > b.height + 1:
        x, y = a.a, a.b
        if x.height >= y.height:
            return _pair(x, _pair(y, b))
        return _pair(_pair(x, y.a), _pair(y.b, b))
    if b.height > a.height + 1:
        x, y = b.a, b.b
        if y.height >= x.height:
            return _pair(_pair(a, x), y)
        return _pair(_pair(a, x.a), _pair(x.b, y))
    return _pair(a, b)


def concat(a, b):
    if a is None:
        return b
    if b is None:
        return a
    if a.n + b.n > MAX:
        raise ValueError('byte length')
    if a is b:
        return repeat(a, 2)
    if a.height > b.height + 1:
        return _balance(a.a, concat(a.b, b))
    if b.height > a.height + 1:
        return _balance(concat(a, b.a), b.b)
    return _pair(a, b)


def join(nodes):
    nodes = [n for n in nodes if n is not None]
    while len(nodes) > 1:
        nodes = [concat(nodes[i], nodes[i+1]) if i+1 < len(nodes) else nodes[i]
                 for i in range(0, len(nodes), 2)]
    return nodes[0] if nodes else None


def repeat(node, count):
    if node is None or count == 0:
        return None
    if count == 1:
        return node
    n = node.n * count
    if n > MAX:
        raise ValueError('byte length')
    if node.kind == 2:
        count *= node.b
        node = node.a
    h, p, bh, bp, k = 0, 1, node.h, node.p, count
    while k:
        if k & 1:
            h, p = (h * bp + bh) & MASK, p * bp & MASK
        bh, bp = (bh * bp + bh) & MASK, bp * bp & MASK
        k >>= 1
    return Bytes(2, n, h, p, 1, node.lf, node, count)


def cut(node, start, end):
    if not 0 <= start <= end <= size(node):
        raise ValueError('slice bounds')
    if start == end:
        return None
    stack, out = [(node, start, end)], []
    while stack:
        node, lo, hi = stack.pop()
        if lo == hi:
            continue
        if lo == 0 and hi == node.n:
            out.append(node)
        elif node.kind == 0:
            out.append(literal(node.a[lo:hi]))
        elif node.kind == 1:
            split = node.a.n
            if hi > split:
                stack.append((node.b, max(0, lo-split), hi-split))
            if lo < split:
                stack.append((node.a, lo, min(hi, split)))
        else:
            child = node.a
            q, r = divmod(lo, child.n)
            last, tail = divmod(hi, child.n)
            pieces = []
            if q == last:
                pieces.append((child, r, tail))
            else:
                if r:
                    pieces.append((child, r, child.n))
                    q += 1
                if last > q:
                    mid = repeat(child, last-q)
                    pieces.append((mid, 0, mid.n))
                if tail:
                    pieces.append((child, 0, tail))
            stack.extend(reversed(pieces))
    return join(out)


def materialize(node, limit=65536):
    return read(node, 0, size(node), limit)


_read_cache = OrderedDict()
_read_bytes = 0


def read(node, start, end, limit=65536):
    """Bounded range access. Repeated ranges expand with C byte repetition,
    not one Python operation per logical repetition."""
    global _read_bytes
    if not 0 <= start <= end <= size(node) or end-start > limit:
        raise ValueError('bounded read')
    out, stack = [], [(0, node, start, end)]
    while stack:
        op, n, lo, hi = stack.pop()
        if op == 3:
            combined = b''.join(out[lo:])
            del out[lo:]
            out.append(combined)
            _read_cache[n] = combined
            _read_bytes += len(combined)
            while _read_bytes > 4*1024*1024 or len(_read_cache) > 4096:
                old, data = _read_cache.popitem(last=False)
                _read_bytes -= len(data)
            continue
        if op == 1:
            combined = b''.join(out[lo:]) * hi
            del out[lo:]
            out.append(combined)
            continue
        if op == 2:
            stack.append((1, None, len(out), hi))
            stack.append((0, n, 0, n.n))
            continue
        if lo == hi:
            continue
        if lo == 0 and hi == n.n and n.kind != 0:
            cached = _read_cache.get(n)
            if cached is not None:
                _read_cache.move_to_end(n)
                out.append(cached)
                continue
            if n.n <= 65536:
                stack.append((3, n, len(out), 0))
        if n.kind == 0:
            out.append(n.a[lo:hi])
        elif n.kind == 1:
            split = n.a.n
            if hi > split:
                stack.append((0, n.b, max(0, lo-split), hi-split))
            if lo < split:
                stack.append((0, n.a, lo, min(hi, split)))
        else:
            first, low = divmod(lo, n.a.n)
            last, high = divmod(hi, n.a.n)
            if first == last:
                stack.append((0, n.a, low, high))
            else:
                if high:
                    stack.append((0, n.a, 0, high))
                if low:
                    first += 1
                if last > first:
                    stack.append((2, n.a, 0, last-first))
                if low:
                    stack.append((0, n.a, low, n.a.n))
    return b''.join(out)


@lru_cache(maxsize=4096)
def ascii_lower(node):
    if node is None:
        return None
    stack, transformed = [(node, False)], {}
    while stack:
        n, ready = stack.pop()
        if n in transformed:
            continue
        if n.kind == 0:
            lower = n.a.lower()
            transformed[n] = n if lower == n.a else literal(lower)
        elif not ready:
            stack.append((n, True))
            stack.append((n.a, False))
            if n.kind == 1:
                stack.append((n.b, False))
        elif n.kind == 1:
            transformed[n] = concat(transformed[n.a], transformed[n.b])
        else:
            transformed[n] = repeat(transformed[n.a], n.b)
    return transformed[node]


def fingerprint(node):
    return {'n': size(node), 'h': f'{node.h if node else 0:016x}'}


def next_lf(node, start=0):
    if node is None or start >= node.n:
        return -1
    stack = [(node, start, 0)]
    while stack:
        n, lo, base = stack.pop()
        if n.lf < 0:
            continue
        if lo <= n.lf:
            return base + n.lf
        if n.kind == 0:
            i = n.a.find(b'\n', lo)
            if i >= 0:
                return base + i
        elif n.kind == 1:
            split = n.a.n
            stack.append((n.b, max(0, lo-split), base+split))
            if lo < split:
                stack.append((n.a, lo, base))
        else:
            q, r = divmod(lo, n.a.n)
            if q+1 < n.b:
                stack.append((n.a, 0, base+(q+1)*n.a.n))
            stack.append((n.a, r, base+q*n.a.n))
    return -1


class Context:
    def __init__(self, definitions, seed):
        self.seed = seed
        self.definitions = {}
        for name, source in definitions:
            if (re.fullmatch(r'[A-Za-z][A-Za-z0-9_]{0,31}', name) is None
                    or keyword.iskeyword(name) or name in self.definitions):
                raise ValueError('definition name')
            self.definitions[name] = self.expression(source)

    def expression(self, text):
        if len(text) > 8192:
            raise ValueError('expression source')
        try:
            tree = ast.parse(text, mode='eval').body
        except (SyntaxError, OverflowError) as exc:
            raise ValueError('expression syntax') from exc
        stack = [(tree, 0)]
        while stack:
            node, depth = stack.pop()
            if depth > 128:
                raise ValueError('expression depth')
            stack.extend((child, depth+1) for child in ast.iter_child_nodes(node))

        def evaluate(node):
            if type(node) is ast.Constant:
                value = node.value
                if type(value) is int and 0 <= value <= MAX:
                    return value
                if type(value) is str:
                    return literal(value.encode('utf8'))
                if type(value) is bytes:
                    return literal(value)
            elif type(node) is ast.Name and node.id in self.definitions:
                return self.definitions[node.id]
            elif type(node) is ast.BinOp:
                a, b = evaluate(node.left), evaluate(node.right)
                if type(node.op) is ast.Add and type(a) is not int and type(b) is not int:
                    return concat(a, b)
                if type(node.op) is ast.Mult:
                    if type(a) is int and type(b) is not int:
                        return repeat(b, a)
                    if type(b) is int and type(a) is not int:
                        return repeat(a, b)
            elif type(node) is ast.Subscript and type(node.slice) is ast.Slice:
                value = evaluate(node.value)
                s = node.slice
                if type(value) is int or s.step is not None:
                    raise ValueError('slice type')
                bounds = []
                for endpoint, default in ((s.lower, 0), (s.upper, size(value))):
                    if endpoint is None:
                        bounds.append(default)
                    elif (type(endpoint) is ast.Constant and type(endpoint.value) is int
                          and 0 <= endpoint.value <= MAX):
                        bounds.append(endpoint.value)
                    else:
                        raise ValueError('slice endpoint')
                return cut(value, *bounds)
            raise ValueError('expression type')

        result = evaluate(tree)
        if type(result) is int:
            raise ValueError('integer result')
        return result

    def template(self, value, coordinate):
        if type(value) is not str:
            raise ValueError('template type')
        value.encode('utf8')
        if value.startswith('{{') and value.endswith('}}'):
            return self.expression(value[2:-2].strip())
        if len(value) > 65536:
            raise ValueError('template source')
        parts = value.split('<<random_string>>')
        if len(parts) > 1:
            out = [parts[0]]
            for i, part in enumerate(parts[1:]):
                out.append(hashlib.sha256(f'{self.seed}/{coordinate}/{i}'.encode('utf8')).hexdigest()[:20])
                out.append(part)
            value = ''.join(out)
        return literal(value.encode('utf8'))

# H3Act offline evidence pipeline

Run `python3 -B main.py` with a single JSON document on stdin. Pydantic and its
pinned dependencies are preinstalled; no network, model, certificate or service
configuration is needed. Read `../PROTOCOL.md` and `../RUNTIME.md` for the contract.

The schema models feed FuzzExecutor, whose frame conversion and HttpClient feed
an injected decoded-event backend. The new byte-program and capture-audit modules
are unfinished. The existing eager expression expansion, frame conversion and
late response waiter also need integration repairs for this offline extension.
The generic socket-free clock provides coroutine plumbing, not an HTTP auditor.

You may edit/reorganize this complete directory and add source/data files within
the published tree budget. No particular internal algorithm or call graph is
required. Functional output must satisfy the complete protocol. A public checker
PASS is only a small sanity result. The initial project is expected to fail it.
"""Offline payload compilation, client replay and origin evidence audit."""
import json
import gc
import math
from pathlib import Path
import re
import sys

# The local no-Docker worker stages the same pinned wheels here. In the public
# image the packages are installed normally and this directory is unnecessary.
if Path('/opt/h3deps').is_dir():
    sys.path.insert(0,'/opt/h3deps')

from schema import compile_cases
from modules.byte_program import Context,MAX
from modules.fuzz_adapter import FuzzExecutor
from modules.capture_audit import audit_channels,TOKEN

NAME = re.compile(r'[A-Za-z0-9_.-]{1,32}\Z',re.ASCII)


def exact(obj,keys):
    if type(obj) is not dict or set(obj)!=set(keys):
        raise ValueError('object keys')


def integer(value,minimum=0,maximum=MAX):
    if type(value) is not int or not minimum <= value <= maximum:
        raise ValueError('integer')
    return value


def sequence(value,maximum):
    if type(value) is not list or len(value)>maximum:
        raise ValueError('array')
    return value


def text(value,maximum=8*1024*1024):
    if type(value) is not str or len(value)>maximum:
        raise ValueError('string')
    value.encode('utf8')
    return value


def pairs(items):
    out = {}
    for key,value in items:
        if key in out:
            raise ValueError('duplicate key')
        out[key] = value
    return out


def bad_constant(value):
    raise ValueError('nonfinite JSON')


def finite_float(value):
    result = float(value)
    if not math.isfinite(result):
        raise ValueError('nonfinite JSON')
    return result


def compile_document(document):
    exact(document,['seed','definitions','timeout_ms','cases','events','channels'])
    seed = text(document['seed'],64)
    if any(c not in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_.-' for c in seed):
        raise ValueError('seed')
    definitions = sequence(document['definitions'],8192)
    for row in definitions:
        sequence(row,2)
        if len(row)!=2:
            raise ValueError('definition pair')
        text(row[0],32)
        text(row[1],8192)
    context = Context(definitions,seed)
    timeout = integer(document['timeout_ms'],1,10**9)
    cases = sequence(document['cases'],2000)
    names = set()
    budget = 0
    fields_count = 0
    for case in cases:
        exact(case,['name','frames','expect'])
        name = text(case['name'],32)
        if not NAME.fullmatch(name) or name in names:
            raise ValueError('case name')
        names.add(name)
        frames = sequence(case['frames'],50000)
        budget += len(frames)
        if budget > 50000:
            raise ValueError('combined budget')
        pause_total = 0
        for frame in frames:
            if type(frame) is not dict or type(frame.get('Type')) is not str:
                raise ValueError('frame')
            if frame['Type']=='sleep':
                pause_total += integer(frame.get('Time_to_Stop'))
            if frame['Type']=='headers':
                if frame.get('headers_kv') is not None:
                    value = frame['headers_kv']
                    if type(value) is not dict:
                        raise ValueError('header mapping')
                    fields_count += len(value)
                    if fields_count > 32768:
                        raise ValueError('header budget')
                elif frame.get('data_to_transfered') is not None:
                    value = sequence(frame['data_to_transfered'],128)
                    fields_count += len(value)
                    if fields_count > 32768:
                        raise ValueError('header budget')
        if pause_total+timeout > MAX:
            raise ValueError('time overflow')
        exp = case['expect']
        exact(exp,['method','target','host'])
        for k in exp:
            value = text(exp[k],8192).encode('ascii')
            if not value or not all(33 <= c <= 126 for c in value):
                raise ValueError('expected identity')
        if TOKEN.fullmatch(exp['method'].encode('ascii')) is None:
            raise ValueError('expected method')
    payload = compile_cases(cases,context)
    payload_dict = payload.model_dump()
    actual_test_cases = {}
    for case_name,frames in payload_dict['test_cases'].items():
        clean_frames = []
        for frame in frames:
            if 'headers_kv' in frame:
                del frame['headers_kv']
            clean_frames.append(frame)
        actual_test_cases[case_name] = clean_frames
    records = sequence(document['events'],50000)
